select t.id,t.fd_state,t.fd_state_code,t.fd_filing_type_code,t.fd_filing_type, t.fd_enter_type_code,t.fd_enter_type,t.fd_car_no,p.fd_driver_name,t.fd_filing_car_type, t.fd_filing_factory_code,t.fd_filing_factory,t.fd_dock_no,t.fd_dock_name,t.fd_dock_department,t.fd_dock_phone, date_format(t.fd_filing_begin,'%Y-%m-%d') fd_filing_begin, date_format(t.fd_filing_end,'%Y-%m-%d') fd_filing_end from safety_enter_filing t left join safety_enter_protect p on t.fd_car_no=p.fd_car_no where t.create_user = #{phoneNo} order by t.fd_state_code,t.create_time desc
limit #{offset}, #{limit}
limit #{limit}

select count(*)
from safety_enter_filing t
where create_user = #{phoneNo}

select f.id
from safety_enter_filing f
left join safety_enter_filing_approve a on f.id=a.fd_filing_id
where 1=1

    and f.fd_dock_no = #{dockNo}


    and f.fd_car_no = #{carNo}


    and a.fd_filing_end > #{date}

and f.fd_state_code in('30','31')

SELECT ef.id from safety_enter_filing ef
INNER JOIN safety_enter_filing_approve fa on ef.id = fa.fd_filing_id
INNER JOIN (select f.fd_car_no,max(a.create_time) create_time
              from safety_enter_filing f,safety_enter_filing_approve a
             where f.id=a.fd_filing_id

            and f.fd_dock_no = #{dockNo}


            and f.fd_car_no = #{carNo}



            and a.fd_filing_end > #{date}
            and a.fd_filing_begin <= #{date}


        and f.fd_state_code in('30','31')
        group by f.fd_car_no) as el
on ef.fd_car_no =el.fd_car_no and  fa.create_time = el.create_time

select * from ( select t.fd_filing_factory_code as factoryCode, date_format(a.fd_filing_begin,'%Y-%m-%d') as beginTime, date_format(a.fd_filing_end,'%Y-%m-%d') as endTime, t.fd_filing_factory as factory, t.create_time from safety_enter_filing t left join safety_enter_filing_per per on t.id = per.filing_id and per.fd_per_type_code = '10' left join safety_enter_filing_approve a on t.id=a.fd_filing_id where t.fd_state_code in ('30','31')
AND t.fd_car_no = #{paramMap.fdCarNo}
AND per.fd_per_card = #{paramMap.fdPerCard}
and ( (a.fd_filing_begin <= concat(#{paramMap.fdFilingBegin},' 23:59:59') and a.fd_filing_end >= concat(#{paramMap.fdFilingBegin},' 00:00:00')) or (a.fd_filing_begin <= concat(#{paramMap.fdFilingEnd},' 23:59:59') and a.fd_filing_end >= concat(#{paramMap.fdFilingEnd},' 00:00:00')) )
union all select t.fd_filing_factory_code as factoryCode, date_format(t.fd_filing_begin,'%Y-%m-%d') as beginTime, date_format(t.fd_filing_end,'%Y-%m-%d') as endTime, t.fd_filing_factory as factory, t.create_time from safety_enter_filing t left join safety_enter_filing_per per on t.id = per.filing_id and per.fd_per_type_code = '10' where t.fd_state_code = '20'
AND t.fd_car_no = #{paramMap.fdCarNo}
AND per.fd_per_card = #{paramMap.fdPerCard}
and ( (t.fd_filing_begin <= concat(#{paramMap.fdFilingBegin},' 23:59:59') and t.fd_filing_end >= concat(#{paramMap.fdFilingBegin},' 00:00:00')) or (t.fd_filing_begin <= concat(#{paramMap.fdFilingEnd},' 23:59:59') and t.fd_filing_end >= concat(#{paramMap.fdFilingEnd},' 00:00:00')) )
)c order by c.create_time desc

select t.fd_filing_factory_code as factoryCode, date_format(a.fd_filing_begin,'%Y-%m-%d') as beginTime, date_format(a.fd_filing_end,'%Y-%m-%d') as endTime, t.fd_filing_factory as factory from safety_enter_filing t left join safety_enter_filing_per per on t.id = per.filing_id and per.fd_per_type_code = '10' left join safety_enter_filing_approve a on t.id=a.fd_filing_id where t.fd_state_code in ('30','31')
AND t.fd_car_no = #{paramMap.fdCarNo}
AND per.fd_per_card = #{paramMap.fdPerCard}
and ( (a.fd_filing_begin <= concat(#{paramMap.fdFilingBegin},' 23:59:59') and a.fd_filing_end >= concat(#{paramMap.fdFilingBegin},' 00:00:00')) or (a.fd_filing_begin <= concat(#{paramMap.fdFilingEnd},' 23:59:59') and a.fd_filing_end >= concat(#{paramMap.fdFilingEnd},' 00:00:00')) )
order by a.create_time desc

select t.id,
       t.fd_filing_factory_code as factoryCode
from safety_enter_filing t
left join safety_enter_filing_approve a on t.id=a.fd_filing_id
where
    t.fd_state_code in ('30','31')
and t.id != #{id}
and a.fd_filing_end > now()

    and t.fd_car_no = #{fdCarNo}



        and (
                    a.fd_filing_begin < #{fdFilingEnd}
                and a.fd_filing_end > #{fdFilingBegin}
            )

update.foreach:
update safety_enter_filing_history set
fd_state = #{l.fdState},
fd_state_code = #{l.fdStateCode}
where fd_filing_id = #{l.id}

mapper.select:
select t.id, t.fd_driver_name, t.fd_car_no, t.fd_enter_type, t.fd_dock_no, tp.flow_id
from safety_enter_filing t
         inner join safety_enter_filing_approve a on t.id = a.fd_filing_id
         inner join safety_enter_process tp on t.id = tp.form_instance_id
where t.fd_car_no = #{carNo}

  and a.fd_filing_begin <= #{carTime}
  and a.fd_filing_end >= #{carTime}

select sf.fd_car_no as carNo, sp.fd_per_name as empName, sp.fd_per_phone as phoneNo from safety_enter_filing sf left join safety_enter_filing_per sp on sf.id = sp.filing_id and sp.fd_per_type_code = '10' where sf.fd_state_code in ('30', '31')
and sf.fd_car_no = #{carNo}
and sp.fd_per_name = #{empName}
and sp.fd_per_phone = #{phoneNo}
order by sf.approve_time desc limit 1
